    },
    shortLegs: {
      do: ['High-waist', 'Nude shoes', 'Monochromatic', 'Pointed-toe shoes', 'Longer tops'],
      avoid: ['Ankle straps (WORST!)', 'Capri length', 'Contrasting shoes/pants', 'Heavy boots'],
    },
