     1→/**
     2→ * Knowledge Base Manager
     3→ *
     4→ * Manages fashion knowledge documents, chunking, and indexing.
     5→ * Supports bilingual content (Thai/English) and metadata filtering.
     6→ *
     7→ * @version 1.0.0
     8→ * @lastUpdated 2025-12-19
     9→ */
    10→
    11→import { RAG_CONFIG, getRAGConfig } from './config';
    12→import { generateEmbedding, generateBatchEmbeddings } from './embeddings';
    13→import {
    14→  initializeVectorStore,
    15→  addDocuments,
    16→  deleteDocuments,
    17→  getDocumentCount,
    18→  listDocumentIds,
    19→  clearIndex,
    20→} from './vector-store';
    21→import type {
    22→  KnowledgeDocument,
    23→  KnowledgeDocumentMetadata,
    24→  KnowledgeCategory,
    25→  DocumentChunk,
    26→  ChunkingConfig,
    27→  VectorStoreEntry,
    28→} from './types';
    29→
    30→// Simple token estimation (4 chars ~ 1 token for English, 2 chars ~ 1 token for Thai)
    31→function estimateTokenCount(text: string): number {
    32→  // Detect Thai characters
    33→  const thaiPattern = /[\u0E00-\u0E7F]/g;
    34→  const thaiMatches = text.match(thaiPattern);
    35→  const thaiCharCount = thaiMatches ? thaiMatches.length : 0;
    36→  const nonThaiCharCount = text.length - thaiCharCount;
    37→
    38→  // Thai: ~2 chars per token, English: ~4 chars per token
    39→  return Math.ceil(thaiCharCount / 2 + nonThaiCharCount / 4);
    40→}
    41→
    42→/**
    43→ * Split text into sentences
    44→ */
    45→function splitIntoSentences(text: string): string[] {
    46→  // Handle both Thai and English sentence endings
    47→  const sentencePattern = /[.!?။ฯ]+[\s\n]+|[\n]{2,}/g;
    48→  const sentences = text.split(sentencePattern).filter((s) => s.trim().length > 0);
    49→  return sentences.map((s) => s.trim());
    50→}
    51→
    52→/**
    53→ * Chunk a document into smaller pieces with overlap
    54→ *
    55→ * @param document - Knowledge document to chunk
    56→ * @param config - Chunking configuration
    57→ * @returns Array of document chunks
    58→ */
    59→export function chunkDocument(
    60→  document: KnowledgeDocument,
    61→  config: ChunkingConfig = RAG_CONFIG.chunking
    62→): DocumentChunk[] {
    63→  const chunks: DocumentChunk[] = [];
    64→  const sentences = splitIntoSentences(document.content);
    65→
    66→  let currentChunk: string[] = [];
    67→  let currentTokens = 0;
    68→  let chunkIndex = 0;
    69→
    70→  for (let i = 0; i < sentences.length; i++) {
    71→    const sentence = sentences[i];
    72→    const sentenceTokens = estimateTokenCount(sentence);
    73→
    74→    // Check if adding this sentence would exceed max tokens
    75→    if (currentTokens + sentenceTokens > config.maxTokens && currentChunk.length > 0) {
    76→      // Create chunk from current content
    77→      const chunkContent = currentChunk.join(' ');
    78→      const chunkTokenCount = estimateTokenCount(chunkContent);
    79→
    80→      // Only add if meets minimum token requirement
    81→      if (chunkTokenCount >= config.minTokens) {
    82→        chunks.push({
    83→          id: `${document.id}_chunk_${chunkIndex}`,
    84→          documentId: document.id,
    85→          chunkIndex,
    86→          content: chunkContent,
    87→          contentThai: document.contentThai
    88→            ? extractThaiChunkContent(document.contentThai, chunkIndex, chunks.length)
    89→            : undefined,
    90→          tokenCount: chunkTokenCount,
    91→          metadata: document.metadata,
    92→        });
    93→        chunkIndex++;
    94→      }
    95→
    96→      // Calculate overlap - keep last N tokens worth of sentences
    97→      const overlapSentences: string[] = [];
    98→      let overlapTokens = 0;
    99→
   100→      for (let j = currentChunk.length - 1; j >= 0 && overlapTokens < config.overlapTokens; j--) {
   101→        overlapSentences.unshift(currentChunk[j]);
   102→        overlapTokens += estimateTokenCount(currentChunk[j]);
   103→      }
   104→
   105→      currentChunk = overlapSentences;
   106→      currentTokens = overlapTokens;
   107→    }
   108→
   109→    currentChunk.push(sentence);
   110→    currentTokens += sentenceTokens;
   111→  }
   112→
   113→  // Don't forget the last chunk
   114→  if (currentChunk.length > 0) {
   115→    const chunkContent = currentChunk.join(' ');
   116→    const chunkTokenCount = estimateTokenCount(chunkContent);
   117→
   118→    if (chunkTokenCount >= config.minTokens) {
   119→      chunks.push({
   120→        id: `${document.id}_chunk_${chunkIndex}`,
   121→        documentId: document.id,
   122→        chunkIndex,
   123→        content: chunkContent,
   124→        contentThai: document.contentThai
   125→          ? extractThaiChunkContent(document.contentThai, chunkIndex, chunks.length)
   126→          : undefined,
   127→        tokenCount: chunkTokenCount,
   128→        metadata: document.metadata,
   129→      });
   130→    } else if (chunks.length > 0) {
   131→      // Merge with previous chunk if last chunk is too small
   132→      const lastChunk = chunks[chunks.length - 1];
   133→      lastChunk.content += ' ' + chunkContent;
   134→      lastChunk.tokenCount = estimateTokenCount(lastChunk.content);
   135→    } else {
   136→      // Document is smaller than minTokens, include as single chunk
   137→      chunks.push({
   138→        id: `${document.id}_chunk_0`,
   139→        documentId: document.id,
   140→        chunkIndex: 0,
   141→        content: chunkContent,
   142→        contentThai: document.contentThai,
   143→        tokenCount: chunkTokenCount,
   144→        metadata: document.metadata,
   145→      });
   146→    }
   147→  }
   148→
   149→  return chunks;
   150→}
   151→
   152→/**
   153→ * Extract corresponding Thai content for a chunk (simplified approach)
   154→ */
   155→function extractThaiChunkContent(
   156→  thaiContent: string,
   157→  chunkIndex: number,
